using System.Windows.Input;
using System.Windows.Media;
using System.Web.Script.Serialization;

internal static class UpdateWords {
    internal static string Text(string en,string es,string language){return language=="es"?es:en;}
    internal static string State(UpdateSnapshot state,string language){switch(state.State){case "Checking":return Text("Checking GitHub for updates…","Buscando actualizaciones en GitHub…",language);case "Available":return Text("A new version is available","Hay una nueva versión disponible",language);case "Current":return state.Release!=null&&state.Release.Version<UpdateManager.CurrentVersion?Text("You have a newer build than the latest published release","Tu versión es más reciente que la última publicada",language):Text("Aion 2 Helper is up to date","Aion 2 Helper está actualizado",language);case "Failed":return Text("Could not check for updates. You can continue using the helper.","No se pudo buscar actualizaciones. Puedes seguir usando el helper.",language);default:return Text("Check for the latest published version","Busca la última versión publicada",language);}}
}
internal sealed class UpdateSettingsPane:StackPanel {
    readonly EnergyOverlay overlay;readonly Window owner;readonly UpdateManager manager;readonly TextBlock title=SettingsVisual.Text("",15),versions=SettingsVisual.Text("",12,"#A7ADBA"),status=SettingsVisual.Text("",12,"#84B8AB");readonly Button check,install;readonly CheckBox startup=new CheckBox();readonly TextBlock startupText=SettingsVisual.Text("",12);bool loading,released;
    internal UpdateSettingsPane(EnergyOverlay overlay,Window owner,UpdateManager manager=null){this.overlay=overlay;this.owner=owner;this.manager=manager??UpdateManager.Shared;Margin=new Thickness(0,16,0,0);var content=new StackPanel();content.Children.Add(title);versions.Margin=new Thickness(0,9,0,0);content.Children.Add(versions);status.Margin=new Thickness(0,10,0,12);content.Children.Add(status);var row=new StackPanel{Orientation=Orientation.Horizontal};check=SettingsVisual.Button("",delegate{this.manager.CheckAsync();});row.Children.Add(check);install=SettingsVisual.Button("",delegate{var update=new UpdateWindow(this.manager,overlay.Language,false);update.Owner=owner;if(update.ShowUpdate())overlay.Close();},true);install.Margin=new Thickness(8,0,0,0);row.Children.Add(install);content.Children.Add(row);var preference=new Grid{Margin=new Thickness(0,14,0,0)};preference.ColumnDefinitions.Add(new ColumnDefinition());preference.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});preference.Children.Add(startupText);Grid.SetColumn(startup,1);preference.Children.Add(startup);content.Children.Add(preference);startup.Click+=delegate{if(loading)return;try{this.manager.StartupPreference(startup.IsChecked==true);}catch(Exception ex){status.Text=UpdateManager.Error(ex);}};Children.Add(SettingsVisual.Card(content,new Thickness(18,16,18,16)));this.manager.Changed+=Changed;Translate();}
    void Changed(){if(released||Dispatcher.HasShutdownStarted)return;try{Dispatcher.BeginInvoke(new Action(Translate));}catch(InvalidOperationException){}}
    internal void Translate(){if(released)return;loading=true;try{string lang=overlay.Language;var state=manager.Read();title.Text=UpdateWords.Text("APPLICATION UPDATES","ACTUALIZACIONES DEL PROGRAMA",lang);versions.Text=UpdateWords.Text("Installed: ","Instalada: ",lang)+UpdateManager.CurrentLabel+"  ·  "+UpdateWords.Text("Latest: ","Última: ",lang)+(state.Release==null?"—":UpdateManager.Label(state.Release.Version));status.Text=UpdateWords.State(state,lang);if(state.State=="Failed"&&state.Error.Length>0)status.Text+="\n"+state.Error;check.Content=UpdateWords.Text("Check for updates","Buscar actualizaciones",lang);check.IsEnabled=state.State!="Checking";install.Content=UpdateWords.Text("Download and update","Descargar y actualizar",lang);install.Visibility=state.State=="Available"?Visibility.Visible:Visibility.Collapsed;startupText.Text=UpdateWords.Text("Check for updates when the helper starts","Buscar actualizaciones al abrir el helper",lang);startup.IsChecked=manager.Preferences.CheckOnStartup;}finally{loading=false;}}
    internal void Release(){released=true;manager.Changed-=Changed;}
}
internal sealed class UpdateWindow:Window {
    readonly UpdateManager manager;readonly string language;readonly bool startup,preview;readonly UpdateCancellation cancellation=new UpdateCancellation();readonly TextBlock heading=SettingsVisual.Text("",25),description=SettingsVisual.Text("",13,"#A7ADBA"),versions=SettingsVisual.Text("",13),detail=SettingsVisual.Text("",12,"#A7ADBA");readonly ProgressBar progress=new ProgressBar{Height=8,Minimum=0,Maximum=100,Foreground=SettingsVisual.Brush("#67C7B0"),Background=SettingsVisual.Brush("#24313B"),BorderThickness=new Thickness(0)};readonly Button accept,decline;bool busy,closed,handedOff,cancelClose;UpdateRelease release;
    internal UpdateWindow(UpdateManager manager,string language,bool startup,bool preview=false){this.manager=manager;this.language=language;this.startup=startup;this.preview=preview;Title="Aion 2 Helper · Update";SettingsVisual.Theme(this);ResizeMode=ResizeMode.NoResize;Width=560;Height=390;ShowInTaskbar=true;var body=new Grid{Margin=new Thickness(28)};Content=SettingsVisual.Shell(body);for(int i=0;i<6;i++)body.RowDefinitions.Add(new RowDefinition{Height=i==4?new GridLength(1,GridUnitType.Star):GridLength.Auto});var brand=SettingsVisual.Text("AION 2 HELPER",11,"#84B8AB");brand.Margin=new Thickness(0,0,0,14);body.Children.Add(brand);Grid.SetRow(heading,1);body.Children.Add(heading);description.Margin=new Thickness(0,10,0,15);Grid.SetRow(description,2);body.Children.Add(description);Grid.SetRow(versions,3);body.Children.Add(versions);var middle=new StackPanel{Margin=new Thickness(0,20,0,10)};middle.Children.Add(progress);detail.Margin=new Thickness(0,10,0,0);middle.Children.Add(detail);Grid.SetRow(middle,4);body.Children.Add(middle);var buttons=new Grid();buttons.ColumnDefinitions.Add(new ColumnDefinition());buttons.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});decline=SettingsVisual.Button("",Decline);decline.HorizontalAlignment=HorizontalAlignment.Left;buttons.Children.Add(decline);accept=SettingsVisual.Button("",Install,true);Grid.SetColumn(accept,1);buttons.Children.Add(accept);Grid.SetRow(buttons,5);body.Children.Add(buttons);brand.MouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){if(e.ButtonState==MouseButtonState.Pressed)DragMove();};Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(busy){e.Cancel=true;Decline();}};Closed+=delegate{closed=true;manager.Changed-=Changed;cancellation.Cancel();};if(!preview){manager.Changed+=Changed;Loaded+=delegate{if(startup)manager.CheckAsync(cancellation);Refresh();};}Render(manager.Read());}
    internal bool ShowUpdate(){ShowDialog();return handedOff;}
    void Dispatch(Action action){if(!closed&&!Dispatcher.HasShutdownStarted)try{Dispatcher.BeginInvoke(new Action(delegate{if(!closed)action();}));}catch(InvalidOperationException){}}
    void Changed(){Dispatch(Refresh);}
    void Refresh(){if(busy)return;var state=manager.Read();if(startup&&(state.State=="Current"||state.State=="Failed")){Close();return;}Render(state);}
    internal void Render(UpdateSnapshot state){release=state.Release;bool available=state.State=="Available";heading.Text=UpdateWords.Text(available?"Update available":"Checking for updates",available?"Actualización disponible":"Buscando actualizaciones",language);description.Text=UpdateWords.Text(available?"A new version of Aion 2 Helper is ready. Would you like to download and install it?":"You can open the helper while the version check finishes.",available?"Hay una nueva versión de Aion 2 Helper. ¿Quieres descargarla e instalarla?":"Puedes abrir el helper mientras termina la búsqueda.",language);versions.Text=UpdateWords.Text("Installed: ","Instalada: ",language)+UpdateManager.CurrentLabel+"  →  "+UpdateWords.Text("Latest: ","Última: ",language)+(release==null?"—":UpdateManager.Label(release.Version));detail.Text=available?UpdateWords.Text("Your settings, combat history and game-tweak backups will be preserved.","Se conservarán tus ajustes, el historial y las copias de seguridad de los ajustes del juego.",language):UpdateWords.State(state,language);progress.IsIndeterminate=!available;progress.Visibility=available?Visibility.Collapsed:Visibility.Visible;accept.Content=UpdateWords.Text("Download and update","Descargar y actualizar",language);accept.IsEnabled=available;decline.Content=UpdateWords.Text(startup?"Not now · Open helper":"Not now",startup?"Ahora no · Abrir helper":"Ahora no",language);}
    void Decline(){if(busy){cancelClose=true;cancellation.Cancel();decline.IsEnabled=false;detail.Text=UpdateWords.Text("Cancelling download…","Cancelando descarga…",language);return;}Close();}
    void StageProgress(string en,string es,double value,bool indeterminate){Dispatch(delegate{detail.Text=UpdateWords.Text(en,es,language);progress.IsIndeterminate=indeterminate;progress.Value=value;});}
    void Install(){if(preview||busy||release==null)return;busy=true;cancelClose=false;accept.IsEnabled=false;decline.Content=UpdateWords.Text("Cancel","Cancelar",language);progress.Visibility=Visibility.Visible;progress.IsIndeterminate=false;progress.Value=0;heading.Text=UpdateWords.Text("Downloading update","Descargando actualización",language);description.Text=UpdateWords.Text("Keep this window open. The helper will restart after installation.","Mantén esta ventana abierta. El helper se reiniciará después de instalar la actualización.",language);var selected=release;ThreadPool.QueueUserWorkItem(delegate{string stage=null;try{stage=UpdateInstaller.NewStage();string archive=Path.Combine(stage,"download.zip");UpdateManager.Download(selected,archive,cancellation,delegate(long done,long total){StageProgress(Math.Round(100.0*done/total)+"% · "+(done/1048576.0).ToString("F1")+" / "+(total/1048576.0).ToString("F1")+" MB",Math.Round(100.0*done/total)+"% · "+(done/1048576.0).ToString("F1")+" / "+(total/1048576.0).ToString("F1")+" MB",100.0*done/total,false);});StageProgress("Verifying and preparing update…","Verificando y preparando la actualización…",100,true);var job=UpdateInstaller.Stage(archive,stage,AppDomain.CurrentDomain.BaseDirectory,selected.Version,cancellation);cancellation.Check();Dispatch(delegate{try{cancellation.Check();UpdateInstaller.Launch(job);busy=false;handedOff=true;Close();}catch(Exception ex){UpdateInstaller.Discard(stage);Failure(ex);}});}catch(Exception ex){UpdateInstaller.Discard(stage);Dispatch(delegate{Failure(ex);});}});}
    void Failure(Exception error){busy=false;if(cancelClose||error is OperationCanceledException){Close();return;}heading.Text=UpdateWords.Text("Update not installed","Actualización no instalada",language);description.Text=UpdateWords.Text("Your current installation has not been changed. You can try again or open the helper.","Tu instalación actual no ha cambiado. Puedes volver a intentarlo o abrir el helper.",language);detail.Text=UpdateManager.Error(error);progress.IsIndeterminate=false;decline.IsEnabled=true;decline.Content=UpdateWords.Text(startup?"Open helper":"Close",startup?"Abrir helper":"Cerrar",language);accept.Content=UpdateWords.Text("Try again","Reintentar",language);accept.IsEnabled=release!=null;}
}
internal sealed class UpdateInstallWindow:Window {
    readonly UpdateJob job;readonly string language;readonly TextBlock title=SettingsVisual.Text("",24),detail=SettingsVisual.Text("",13,"#A7ADBA");readonly ProgressBar progress=new ProgressBar{Height=8,Minimum=0,Maximum=100,Foreground=SettingsVisual.Brush("#67C7B0"),Background=SettingsVisual.Brush("#24313B")};bool working=true;
    internal UpdateInstallWindow(UpdateJob job,string language){this.job=job;this.language=language;SettingsVisual.Theme(this);Title="Aion 2 Helper · Installing update";ResizeMode=ResizeMode.NoResize;Width=560;Height=270;var body=new StackPanel{Margin=new Thickness(28)};body.Children.Add(SettingsVisual.Text("AION 2 HELPER",11,"#84B8AB"));title.Text=UpdateWords.Text("Installing update","Instalando actualización",language);title.Margin=new Thickness(0,16,0,12);body.Children.Add(title);body.Children.Add(progress);detail.Margin=new Thickness(0,14,0,0);body.Children.Add(detail);Content=SettingsVisual.Shell(body);Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){e.Cancel=working;};Loaded+=delegate{ThreadPool.QueueUserWorkItem(delegate{try{UpdateInstaller.WaitForParent(job,Progress);UpdateInstaller.Apply(job,Progress,delegate{UpdateInstaller.VerifyInstalled(job);});Progress(100,"Restarting Aion 2 Helper…");UpdateInstaller.Restart(job);Dispatcher.BeginInvoke(new Action(delegate{working=false;Close();}));}catch(Exception ex){Dispatcher.BeginInvoke(new Action(delegate{working=false;title.Text=UpdateWords.Text("Update could not finish","No se pudo completar la actualización",language);detail.Text=ex.Message;var button=SettingsVisual.Button(UpdateWords.Text("Open helper","Abrir helper",language),delegate{try{UpdateInstaller.Restart(job);Close();}catch(Exception launch){detail.Text=launch.Message;}},true);button.Margin=new Thickness(0,14,0,0);body.Children.Add(button);Height=400;}));}});};}
    void Progress(int percent,string message){Dispatcher.BeginInvoke(new Action(delegate{progress.Value=percent;detail.Text=message=="Waiting for Aion 2 Helper to close…"?UpdateWords.Text(message,"Esperando a que se cierre Aion 2 Helper…",language):message=="Installing update…"?UpdateWords.Text(message,"Instalando actualización…",language):message=="Checking the updated application…"?UpdateWords.Text(message,"Comprobando la aplicación actualizada…",language):UpdateWords.Text(message,"Reiniciando Aion 2 Helper…",language);}));}
}
internal static class UpdateRuntime {
    internal static string Language(string root){try{var path=Path.Combine(root,"overlay-settings.json");if(File.Exists(path)&&new FileInfo(path).Length<2*1024*1024)return UiLanguage.Read(new JavaScriptSerializer{MaxJsonLength=2*1024*1024}.Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(path)));}catch(Exception e){if(!(e is IOException||e is UnauthorizedAccessException||e is ArgumentException||e is InvalidOperationException))throw;}return "en";}
    internal static bool Startup(string root){if(!UpdateManager.Shared.Preferences.CheckOnStartup)return false;return new UpdateWindow(UpdateManager.Shared,Language(root),true).ShowUpdate();}
    internal static int Apply(string path){try{var job=UpdateInstaller.Load(path);new UpdateInstallWindow(job,Language(job.Root)).ShowDialog();return 0;}catch(Exception ex){System.Windows.Forms.MessageBox.Show(ex.Message,"Aion 2 Helper · Update",System.Windows.Forms.MessageBoxButtons.OK,System.Windows.Forms.MessageBoxIcon.Error);return 1;}}
}
